package file

import (
	"fmt"
	"os/exec"
	"strings"
)

type AfsClient struct {
	CmdPrefix string
	UserName  string
	Password  string
}

func NewAfsClient(cmdPrefix, userName, password string) *AfsClient {
	afsClient := &AfsClient{
		CmdPrefix: cmdPrefix,
		UserName:  userName,
		Password:  password,
	}
	return afsClient
}

func (c *AfsClient) exec(cmd string) error {
	var err error
	retryTime := 3
	for ; retryTime > 0; retryTime-- {
		execCmd := exec.Command("bash", "-c", cmd)
		_, err = execCmd.Output()
		if err == nil {
			break
		}
	}
	return err
}

func (c *AfsClient) execOut(cmd string) (string, error) {
	var err error
	retryTime := 3
	for ; retryTime > 0; retryTime-- {
		execCmd := exec.Command("bash", "-c", cmd)
		out, err := execCmd.Output()
		if err == nil {
			return string(out), nil
		}
	}
	return "", err
}

func (c *AfsClient) Get(from, to string) error {
	cmd := fmt.Sprintf("%s --username=%s --password=%s get %s %s", c.CmdPrefix, c.UserName, c.Password, from, to)
	return c.exec(cmd)
}

func (c *AfsClient) Ls(path string) ([]string, error) {
	cmd := fmt.Sprintf("%s --username=%s --password=%s ls %s", c.CmdPrefix, c.UserName, c.Password, path)
	// 执行命令并获取输出
	out, err := c.execOut(cmd)
	if err != nil {
		return nil, err
	}

	// 分割输出以获取目录列表
	dirs := strings.Split(strings.TrimSpace(out), "\n")
	return dirs, nil
}

func (c *AfsClient) Put(from, to string) error {
	cmd := fmt.Sprintf("%s --username=%s --password=%s put --override %s %s", c.CmdPrefix, c.UserName, c.Password, from, to)
	return c.exec(cmd)
}

func (c *AfsClient) Mkdir(dir string) error {
	cmd := fmt.Sprintf("%s --username=%s --password=%s mkdir %s ", c.CmdPrefix, c.UserName, c.Password, dir)
	return c.exec(cmd)
}

func (c *AfsClient) Remove(path string) error {
	cmd := fmt.Sprintf("%s --username=%s --password=%s rm --recursive %s ", c.CmdPrefix, c.UserName, c.Password, path)
	return c.exec(cmd)
}

