	if err != nil {
		return err
	}

	if len(shopFiles) == 0 {
		return fmt.Errorf("no shopinfo files found in directory %s/shopinfo", dir)
	}

	// 按文件名排序以确保一致性
	sort.Strings(shopFiles)

