<old_string><![CDATA[// mergeFiles 合并目录中的所有文件到一个目标文件
func (p *OpeDownload) mergeFiles(ctx context.Context, sourceDir, targetFile string) error {
	// 读取源目录中的所有文件
	files, err := filepath.Glob(sourceDir + "/*")
	if err != nil {
		return err
	}

	if len(files) == 0 {
		return fmt.Errorf("no files found in directory %s", sourceDir)
	}

	// 创建目标文件
	target, err := os.Create(targetFile)
	if err != nil {
		return err
	}
	defer target.Close()

	writer := bufio.NewWriter(target)
	defer writer.Flush()

	// 按文件名排序以确保一致性
	sort.Strings(files)

	// 合并所有文件内容
	for _, filePath := range files {
		fileInfo, err := os.Stat(filePath)
		if err != nil {
			log.Warn(ctx, "Error stating file %s, err:%v", filePath, err.Error())
			continue
		}

		// 跳过目录
		if fileInfo.IsDir() {
			continue
		}

		sourceFile, err := os.Open(filePath)
		if err != nil {
			log.Warn(ctx, "Error opening file %s, err:%v", filePath, err.Error())
			continue
		}

		scanner := bufio.NewScanner(sourceFile)
		for scanner.Scan() {
			line := scanner.Text()
			_, err := writer.WriteString(line + "\n")
			if err != nil {
				sourceFile.Close()
				return err
			}
		}

		sourceFile.Close()
		if err := scanner.Err(); err != nil {
			log.Warn(ctx, "Error reading file %s, err:%v", filePath, err.Error())
		}
	}

	log.Notice(ctx, "Merged %d files from %s to %s", len(files), sourceDir, targetFile)
	return nil
}]]></old_string>
