	"icode.baidu.com/baidu/mapsearch/richdata/library/file"
	"icode.baidu.com/baidu/mapsearch/richdata/log"
)

var countFields map[string]int = make(map[string]int)
var fileIndex = 1

type ShopInfo struct {
	ShopID         string        `json:"shopId"`
	ShopUUID       string        `json:"shopUuid"`
	Name           string        `json:"name"`
	BusinessStatus int           `json:"businessStatus"`
	FrontCate      string        `json:"frontCate"`
